#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int y, cap, flow, cost;
    Edge() {}
    Edge(int y, int cap, int flow, int cost) : y(y), cap(cap), flow(flow), cost(cost) {}
};

vector<Edge> graph_edges;
const int MAXN = 14043;
vector<int> adj[MAXN];

long long total_flow_cost = 0;
long long dist[MAXN];
int parent_node[MAXN], parent_edge_idx[MAXN], in_queue[MAXN];

const long long INF = 1e18;
int s = MAXN - 2;
int t = MAXN - 1;

int residual(int idx) {
    return graph_edges[idx].cap - graph_edges[idx].flow;
}

void find_augmenting_path() {
    for (int i = 0; i < MAXN; i++) {
        dist[i] = INF;
        parent_node[i] = -1;
        parent_edge_idx[i] = -1;
        in_queue[i] = 0;
    }
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    in_queue[s] = 1;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        in_queue[u] = 0;
        for (auto e_idx : adj[u]) {
            if (residual(e_idx) == 0) continue;
            int y = graph_edges[e_idx].y;
            int cst = graph_edges[e_idx].cost;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                parent_node[y] = u;
                parent_edge_idx[y] = e_idx;
                if (!in_queue[y]) {
                    in_queue[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int cur = t;
    while (cur != s) {
        graph_edges[parent_edge_idx[cur]].flow++;
        graph_edges[parent_edge_idx[cur] ^ 1].flow--;
        cur = parent_node[cur];
    }
    total_flow_cost += dist[t];
}

void create_edge(int from, int to, int capacity, int cost) {
    adj[from].push_back(graph_edges.size());
    graph_edges.emplace_back(to, capacity, 0, cost);
    adj[to].push_back(graph_edges.size());
    graph_edges.emplace_back(from, 0, 0, -cost);
}

int main() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    for (int i = 0; i < k; i++) {
        int x; cin >> x; --x;
        create_edge(s, x, 1, 0);
    }
    int T = 101;
    for (int i = 0; i < T; i++)
        create_edge(i * n, t, k, i * c);
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y; --x; --y;
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                create_edge(x + i * n, y + i * n + n, 1, d * (j * 2 + 1));
            }
        }
        for (int i = 0; i < T - 1; i++) {
            for (int j = 0; j < k; j++) {
                create_edge(y + i * n, x + i * n + n, 1, d * (j * 2 + 1));
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < T - 1; j++) {
            create_edge(i + j * n, i + j * n + n, k, 0);
        }
    }
    for (int i = 0; i < k; i++) {
        find_augmenting_path();
    }
    cout << total_flow_cost << endl;
}
